command:
// DSCT: Search
//
// The Search maneuver posted as its own chat message rather than as part of an ability card.
//
// Select the creature searching and run this. It rolls the Intuition test, lists every hidden
// creature in range as its own row, and lets whoever owns them roll to stay hidden. Beating a
// creature reveals it, and the searcher can point it out to allies within 10 squares.
//
// Use the Search ability from your sheet instead if you want the card with the rules text.

const api = game.modules.get('draw-steel-combat-tools')?.api;
if (!api) return ui.notifications.error('Draw Steel: Combat Tools is not active.');

const token = canvas.tokens.controlled[0];
if (!token) return ui.notifications.warn('Select the creature searching first.');

await api.stealth.search(token);
